// === Tab: mySketch.js ===
//
//		<= Contribution to the Creative Code Challenge by @sableraph (https://discord.gg/xeyPrcrmKJ) => 
// So for the topic of obscure, i wanted to play around with voronoi noise again.
// The idea was to have a couple of points floating around and merging into a cloud looking thing using voronoi noise implemented as a shader
// That didnt quite look how i intended to so after some playing around i settled on the cell shading-ish effect with the multiple layers
// And after some more playing around with the color proportions the points started to merge into each other and appear / dissapear wherever their density was high or low respectfully
// I dont fully comprehend how that effect came about so i guess in that way not only the art piece is obscure but also the code.
//

const maxPoints = 10;
const maxSpeed = 0.2;
const speedScaling = 2;
const proportions = [0.5, 0.3, .2]
let pointTypes = [];

let theShader;
let points = [];
let directions = [];

function preload() {
	theShader = loadShader('https://openprocessing.org/sketch/2126807/files/shader.vert', 'shader.frag');
}

function setup() {
	describe("3 separate point clouds with distinct different colors (that when combined add to white) float around on the canvas and create a emerging pattern based on voronoi noise and cell shading");
	pointTypes= [color(proportions[0] * 255, proportions[1] * 255, proportions[2] * 255),
							color(proportions[2] * 255, proportions[0] * 255, proportions[1] * 255),
							color(proportions[1] * 255, proportions[2] * 255, proportions[0] * 255)]

	canvas = createCanvas(4/3*windowHeight, windowHeight, WEBGL);
	canvas.position(140,0);
	pixelDensity(1);
	background(255);
	noStroke();
	for(let j = 0; j < pointTypes.length; j++) {
		let newPoints = [];
		let newDirections = [];
		for(let i = 0; i < maxPoints; i++) {
			newPoints[i] = createVector((random() - 0.5) * width, (random() - 0.5) * height);
			newDirections[i] = p5.Vector.random2D().mult(100);
		}
		points[j] = newPoints;
		directions[j] = newDirections;
	}
}

function draw() {	
	for(let i = 0; i < pointTypes.length; i++) {
		updatePoints(i);
	}

	theShader.setUniform('u_mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), height - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
	theShader.setUniform('u_resolution', [width, height]);
	theShader.setUniform('u_points', getRawVectorArray());
	theShader.setUniform('u_colors', getRawTypeColors());
	shader(theShader);
	rect(0, 0, width, height);
}

function updatePoints(type) {
	var newPoints = [maxPoints];
	for(let i = 0; i < points[type].length; i++) {
		newPoints[i] = updatePoint(type, i);
	}
	points[type] = newPoints;
}

function updatePoint(type, index) {
	let newDirection = createVector(0, 0);
	newDirection.add(p5.Vector.mult(points[type][index], -1).limit(maxSpeed));

	for(let i = 0; i < maxPoints; i++) {
		if(index == i) { //dont get the distance to itself
			continue;
		}
		//get difference
		let diffVec = p5.Vector.sub(points[type][i], points[type][index]);
		//let diffVec = createVector(0, 0);
		diffVec.limit(maxSpeed);
		//add to total
		newDirection.add(diffVec);
	}

	directions[type][index].add(newDirection);

	let newPoint = p5.Vector.add(points[type][index], p5.Vector.mult(directions[type][index], deltaTime * 0.001 * speedScaling));
	return newPoint;
}

function getRawVectorArray() {
	let rawArray = []; //maxPoints * pointTypes.length
	for(let j = 0; j < pointTypes.length; j++) {
		for(let i = 0; i < maxPoints; i++) {
			rawArray[2 * j * maxPoints + i * 2] = points[j][i].x;
			rawArray[2 * j * maxPoints + i * 2 + 1] = points[j][i].y;
		}
	}
	return rawArray;
}

function getRawTypeColors() {
	var rawArray = []; //pointTypes.length * 3
	for(let i = 0; i < pointTypes.length; i++) {
		rawArray[3 * i + 0] = red(pointTypes[i]) / 255.0;
		rawArray[3 * i + 1] = green(pointTypes[i]) / 255.0;
		rawArray[3 * i + 2] = blue(pointTypes[i]) / 255.0;
	}
	return rawArray;
}


function mousePressed() {
  if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) {
    let fs = fullscreen();
    fullscreen(!fs);
  }
}

function windowResized() {
  resizeCanvas(width, height);
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}


// === Tab: shader.vert ===
#ifdef GL_ES

precision mediump float;

#endif



attribute vec3 aPosition;



void main() {

  vec4 positionVec4 = vec4(aPosition, 1.0);

  // scale the rect by two, and move it to the center of the screen
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  gl_Position = positionVec4;
}

// === Tab: shader.frag ===
#ifdef GL_ES

precision mediump float;

#endif

#define GRADIENT_STEPS 10.0
#define TYPES 3
#define MAX_POINTS 10

uniform vec2 u_mouse;
uniform vec2 u_resolution;
uniform float u_points[MAX_POINTS * TYPES * 2];
uniform float u_colors[TYPES * 3];
float minDist[TYPES];

void main() {
		vec2 pixelPosition = gl_FragCoord.xy - u_resolution.xy * 0.5;
		vec3 color = vec3(0);
		for(int j = 0; j < TYPES; j++) {
			minDist[j] = length(u_resolution.xy);
			for(int i = 0; i < MAX_POINTS; i++) {
				vec2 distVec = (vec2(u_points[2 * j * MAX_POINTS + i * 2], u_points[2 * j * MAX_POINTS + i * 2 + 1]).xy - pixelPosition.xy) / (u_resolution.yy * 0.2);
				minDist[j] = min(minDist[j], length(distVec));
			}
			color += vec3(u_colors[j * TYPES], u_colors[j * TYPES + 1], u_colors[j * TYPES + 2]) * (1.0 - minDist[j] * minDist[j]);
		}

		gl_FragColor = vec4(ceil(color.xyz * GRADIENT_STEPS) / GRADIENT_STEPS, 1);
}

